def transform(grid):
    """Keep near-solid non-background rectangular fields; erase scattered marks."""
    h, w = len(grid), len(grid[0])
    from collections import Counter
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background for _ in range(w)] for _ in range(h)]

    # Per-color summed-area tables let us detect rectangles with a few corrupted
    # cells (the scattered symbols inside fields) without relying on coordinates.
    colors = set(v for row in grid for v in row) - {background}
    for color in colors:
        pref = [[0] * (w + 1) for _ in range(h + 1)]
        for r in range(h):
            run = 0
            for c in range(w):
                run += (grid[r][c] == color)
                pref[r + 1][c + 1] = pref[r][c + 1] + run
        for r0 in range(h - 1):
            for r1 in range(r0 + 1, h):
                rh = r1 - r0 + 1
                for c0 in range(w - 1):
                    for c1 in range(c0 + 1, w):
                        area = rh * (c1 - c0 + 1)
                        if area < 6:
                            continue
                        count = (pref[r1 + 1][c1 + 1] - pref[r0][c1 + 1]
                                 - pref[r1 + 1][c0] + pref[r0][c0])
                        if count * 5 >= area * 4:
                            for r in range(r0, r1 + 1):
                                for c in range(c0, c1 + 1):
                                    out[r][c] = color
    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[background] * w for _ in range(h)]
    seen = [[False] * w for _ in range(h)]
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == background or seen[r][c]:
                continue
            q = deque([(r, c)])
            seen[r][c] = True
            cells = []
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= ny < h and 0 <= nx < w and not seen[ny][nx] and grid[ny][nx] == color:
                        seen[ny][nx] = True
                        q.append((ny, nx))
            r0 = min(y for y, x in cells); r1 = max(y for y, x in cells)
            c0 = min(x for y, x in cells); c1 = max(x for y, x in cells)
            area = (r1-r0+1) * (c1-c0+1)
            # The intended objects are near-solid rectangles; foreign specks
            # (including their identifying marks) interrupt but do not erase them.
            if area >= 6 and len(cells) * 4 >= area * 3:
                for y in range(r0, r1+1):
                    for x in range(c0, c1+1):
                        out[y][x] = color
    return out

