def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = max(set(v for row in grid for v in row), key=lambda v: sum(r.count(v) for r in grid))
    mark = next(v for v in set(v for row in grid for v in row) if v != bg)
    fill = 2
    for r in range(h):
        cols = [c for c, v in enumerate(grid[r]) if v == mark]
        for a, b in zip(cols, cols[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    for c in range(w):
        rows = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rows, rows[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    return out

def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    vals = {x for row in grid for x in row}
    bg = max(vals, key=lambda x: sum(row.count(x) for row in grid))
    mark = next(x for x in vals if x != bg)
    fill = 2
    # Complete short interrupted straight strokes, but don't bridge across
    # the large interiors of open outlines.
    max_gap = h
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cs, cs[1:]):
            if b-a-1 <= max_gap:
                for c in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = fill
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rs, rs[1:]):
            if b-a-1 <= max_gap:
                for r in range(a+1,b):
                    if grid[r][c] == bg: out[r][c] = fill
    return out

def transform(grid):
    h, w = len(grid), len(grid[0])
    from collections import Counter
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    mark = next(x for x in counts if x != bg)
    fill = 2
    out = [row[:] for row in grid]
    # Fill missing cells between successive marks in each row and column.
    for r in range(h):
        cs = [c for c in range(w) if grid[r][c] == mark]
        for a, b in zip(cs, cs[1:]):
            for c in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    for c in range(w):
        rs = [r for r in range(h) if grid[r][c] == mark]
        for a, b in zip(rs, rs[1:]):
            for r in range(a + 1, b):
                if grid[r][c] == bg:
                    out[r][c] = fill
    # Join nearby diagonal breaks as two orthogonal legs (the elbow at
    # the row of the first point and column of the second).
    pts = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == mark]
    for r1,c1 in pts:
        for r2,c2 in pts:
            if (r1,c1) >= (r2,c2):
                continue
            if abs(r1-r2) <= 2 and abs(c1-c2) <= 2 and r1 != r2 and c1 != c2:
                # For short diagonal-near pairs, draw the two legs via the upper-row/other-column elbow.
                if grid[r1][c2] == bg or grid[r1][c2] == fill:
                    for c in range(min(c1,c2)+1, max(c1,c2)):
                        if grid[r1][c] == bg: out[r1][c] = fill
                    for r in range(min(r1,r2)+1, max(r1,r2)):
                        if grid[r][c2] == bg: out[r][c2] = fill
    return out

def transform(grid):
    """Connect aligned markers, using 2 for the cells between them."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    background = max(counts, key=counts.get)
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != background and grid[r][c] != 2]
    out = [row[:] for row in grid]
    for i, (r, c, color) in enumerate(markers):
        for rr, cc, other in markers[i + 1:]:
            if other != color:
                continue
            if r == rr:
                for x in range(min(c, cc) + 1, max(c, cc)):
                    if out[r][x] == background:
                        out[r][x] = 2
            elif c == cc:
                for y in range(min(r, rr) + 1, max(r, rr)):
                    if out[y][c] == background:
                        out[y][c] = 2
    return out

