def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    d4 = ((1, 0), (-1, 0), (0, 1), (0, -1))
    d8 = tuple((dy, dx) for dy in (-1, 0, 1) for dx in (-1, 0, 1) if dy or dx)

    # Zero regions use edge connectivity; a region not reaching the canvas edge
    # is an enclosed cavity. Record the 1-components that bound such cavities.
    zseen = [[False] * w for _ in range(h)]
    enclosed = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 or zseen[r][c]:
                continue
            q = deque([(r, c)])
            zseen[r][c] = True
            comp = []
            edge = False
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    edge = True
                for dy, dx in d4:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and not zseen[yy][xx]:
                        zseen[yy][xx] = True
                        q.append((yy, xx))
            if not edge:
                enclosed.append(comp)

    # Label 8-connected line components so an open neighboring object is not
    # recolored merely because some other object encloses a cavity.
    label = [[-1] * w for _ in range(h)]
    components = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] != 1 or label[r][c] != -1:
                continue
            idx = len(components)
            q = deque([(r, c)])
            label[r][c] = idx
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for dy, dx in d8:
                    yy, xx = y + dy, x + dx
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1 and label[yy][xx] == -1:
                        label[yy][xx] = idx
                        q.append((yy, xx))
            components.append(comp)

    closed_ids = set()
    for comp in enclosed:
        touching = set()
        for y, x in comp:
            for dy, dx in d8:
                yy, xx = y + dy, x + dx
                if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 1:
                    touching.add(label[yy][xx])
        closed_ids.update(touching)
        # Color only the inner rim of each enclosed zero area.
        for y, x in comp:
            if any(0 <= y + dy < h and 0 <= x + dx < w and grid[y + dy][x + dx] == 1 for dy, dx in d8):
                out[y][x] = 3

    # Color the one-cell outer rim of closed line components.
    for idx in closed_ids:
        for y, x in components[idx]:
            for dy, dx in d8:
                yy, xx = y + dy, x + dx
                if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] == 0 and zseen[yy][xx]:
                    # Do not overwrite an enclosed-area color.
                    if out[yy][xx] == 0:
                        out[yy][xx] = 2
    return out

