    n = len(grid[0])
    out = [[0] * n for _ in range(n)]
    center = next(c for c, value in enumerate(grid[0]) if value == 2)
    split = n // 2
    for r in range(n):
        left, right = center - r, center + r
        for c in range((r - center) % 4, n, 4):
            if left <= c <= right:
                out[r][c] = 1
        if r <= split:
            for c in (left, right):
                if 0 <= c < n:
                    out[r][c] = 2
    return out

