from collections import deque


def transform(grid):
    """List the colors of non-background objects in descending color order."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for c in row:
            counts[c] = counts.get(c, 0) + 1
    background = max(counts, key=counts.get)
    seen = set()
    colors = []
    for r in range(h):
        for c in range(w):
            if (r, c) in seen or grid[r][c] == background:
                continue
            color = grid[r][c]
            colors.append(color)
            q = deque([(r, c)])
            seen.add((r, c))
            while q:
                y, x = q.popleft()
                for ny, nx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if (0 <= ny < h and 0 <= nx < w and
                            (ny,nx) not in seen and grid[ny][nx] == color):
                        seen.add((ny,nx))
                        q.append((ny,nx))
    colors.sort(reverse=True)
    colors = (colors + [0] * 6)[:6]
    return [colors[:3], colors[3:]]

def transform(grid):
    """Complete the periodic pattern of monochromatic parallel lines."""
    h, w = len(grid), len(grid[0])
    line_keys = {
        'row': lambda r, c: r,
        'column': lambda r, c: c,
        'diag': lambda r, c: r - c,
        'anti': lambda r, c: r + c,
    }
    points = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] != 0]
    if not points:
        raise ValueError('no pattern lines')
    candidates = []
    for name, key_fn in line_keys.items():
        groups = {}
        valid = True
        for r, c, color in points:
            key = key_fn(r, c)
            if key in groups and groups[key] != color:
                valid = False
                break
            groups[key] = color
        if valid:
            n = len(groups)
            phase = {}
            for key, color in groups.items():
                residue = key % n
                if residue in phase and phase[residue] != color:
                    valid = False
                    break
                phase[residue] = color
            if valid and len(phase) == n:
                candidates.append((n, name, key_fn, phase))
    if not candidates:
        raise ValueError('clues do not define a complete periodic line pattern')
    _, _, key_fn, phase = min(candidates, key=lambda item: item[0])
    return [[phase[key_fn(r, c) % len(phase)] for c in range(w)] for r in range(h)]

