        raise ValueError('No solid divider with equal-sized panels')
    first, second = candidates[0]
    shared = {v for row in first for v in row} & {v for row in second for v in row}
    if len(shared) != 1:
        raise ValueError(f'Expected a single shared panel color, got {shared}')
    common = next(iter(shared))
    return [[3 if a == b == common else common for a, b in zip(ra, rb)]
            for ra, rb in zip(first, second)]

