    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]

    # Infer the cycle length and phase-to-color map from the visible interior.
    # The colored interior advances one cycle step for each step right or down.
    samples = [(r, c, grid[r][c])
               for r in range(3, h) for c in range(3, w)
               if grid[r][c] != 0]
    best = None
    for period in range(2, 11):
        by_phase = defaultdict(Counter)
        for r, c, color in samples:
            by_phase[(r + c) % period][color] += 1
        phase_color = {phase: counts.most_common(1)[0][0]
                       for phase, counts in by_phase.items()}
        score = sum(phase_color[(r + c) % period] == color
                    for r, c, color in samples)
